	static bool RWReportTracker(void const* owner, std::string const& url, unsigned kind,
        std::size_t count, bool stopped, tcp::endpoint const* endpoint = nullptr)
    {
        if (!RWObserveTracker) return false;
        RWTrackerObservation e{};e.version=1;e.kind=kind;e.torrent=owner;
        e.url=url.data();e.url_length=static_cast<uint32_t>(std::min(url.size(),std::size_t(UINT32_MAX)));
        e.count=static_cast<uint32_t>(std::min(count,std::size_t(UINT32_MAX)));e.stopped=stopped;
        if(endpoint){e.port=endpoint->port();
            if(endpoint->address().is_v4()){auto bytes=endpoint->address().to_v4().to_bytes();e.address_length=4;std::copy(bytes.begin(),bytes.end(),e.address);}
            else{auto address=endpoint->address().to_v6();auto bytes=address.to_bytes();e.address_length=16;e.scope=address.scope_id();std::copy(bytes.begin(),bytes.end(),e.address);}
        }
        return RWObserveTracker(&e);
    }

